def solve(n, edges):
    import heapq
    graph=[[] for _ in range(n)]; degree=[0]*n
    for u,v in edges: graph[u].append(v); degree[v]+=1
    available=[u for u in range(n) if degree[u]==0]; heapq.heapify(available)
    order=[]
    while available:
        u=heapq.heappop(available); order.append(u)
        for v in graph[u]:
            degree[v]-=1
            if degree[v]==0: heapq.heappush(available,v)
    return order if len(order)==n else []
